"""Builds the body of the build comment of a pull request (see pull-request-comment.yml).

The newest commit is listed in full at the top, the commits before it are folded into a <details> block, each in its own
<details> block. Every commit has a section delimited by hidden markers, so that a later run can update exactly that
section and keep the others as they are. Prints the new comment to stdout.
"""
import argparse
import re

MARKER = '<!-- blitzllvm-pr-build -->'
MAX_OLDER = 20
SECTION = re.compile(r'<!-- build:(?P<sha>[0-9a-f]{7}) (?P<state>pending|success|cancelled|failure) -->\n(?P<body>.*?)\n<!-- /build -->', re.S)
TITLES = {
    'pending': '⏳ Build pending',
    'success': '✅ Build succeeded',
    'cancelled': '⚪ Build cancelled',
    'failure': '❌ Build failed',
}


def section(sha, state, run_url, rows):
    lines = [f'Commit `{sha}` · [Workflow run]({run_url})', '']
    if state == 'pending':
        lines.append('The binaries will be listed here once the build finished.')
    elif rows:
        lines += ['| Binaries | Size |', '| --- | --- |', *rows, '',
                  '_Downloading artifacts requires being signed in to GitHub. They expire after 90 days._']
    else:
        lines.append('No binaries were produced.')
    return '\n'.join(lines)


def main():
    p = argparse.ArgumentParser()
    p.add_argument('--sha', required=True)
    p.add_argument('--state', required=True, choices=TITLES)
    p.add_argument('--run-url', required=True)
    p.add_argument('--rows', help='file with the table rows of the binaries')
    p.add_argument('--previous', help='file with the previous comment')
    a = p.parse_args()

    sha = a.sha[:7]
    if not re.fullmatch(r'[0-9a-f]{7}', sha):
        raise SystemExit('Invalid commit.')
    rows = open(a.rows).read().splitlines() if a.rows else []

    # Previous sections by commit, newest first. The one being reported replaces its older self and moves to the top.
    older = []
    if a.previous:
        for m in SECTION.finditer(open(a.previous).read()):
            if m.group('sha') != sha:
                older.append((m.group('sha'), m.group('state'), m.group('body')))
    entries = [(sha, a.state, section(sha, a.state, a.run_url, rows))] + older

    out = [MARKER]
    for i, (s, state, body) in enumerate(entries[:MAX_OLDER + 1]):
        block = f'<!-- build:{s} {state} -->\n{body}\n<!-- /build -->'
        if i == 0:
            out.append(f'## {TITLES[state]}\n\n{block}')
        else:
            if i == 1:
                out.append('\n<details>\n<summary>Older commits</summary>\n')
            out.append(f'<details>\n<summary>{TITLES[state]} · <code>{s}</code></summary>\n\n{block}\n\n</details>\n')
    if len(entries) > 1:
        out.append('</details>')
    print('\n'.join(out))


if __name__ == '__main__':
    main()
